// TaskyServer is the server API for Tasky service.
// All implementations must embed UnimplementedTaskyServer
// for forward compatibility.
//
// Tasky — тонкий CRUD-сервис, зеркало интерфейса store.Store.
type TaskyServer interface {
	// Проекты.
	ListProjects(context.Context, *Empty) (*ProjectListResponse, error)
	CreateProject(context.Context, *ProjectNameRequest) (*ProjectResponse, error)
	DeleteProject(context.Context, *IDRequest) (*Empty, error)
	ProjectDescription(context.Context, *IDRequest) (*StringResponse, error)
	UpdateProjectDescription(context.Context, *TextRequest) (*Empty, error)
	ProjectLinks(context.Context, *ProjectIDRequest) (*LinkListResponse, error)
	CreateProjectLink(context.Context, *LinkOwnerRequest) (*LinkResponse, error)
	UpdateProjectLink(context.Context, *LinkNameRequest) (*LinkResponse, error)
	DeleteProjectLink(context.Context, *IDRequest) (*Empty, error)
	ProjectLinksTexts(context.Context, *Empty) (*ProjectLinksTextsResponse, error)
	// Задачи и подзадачи.
	TasksByProject(context.Context, *ProjectIDRequest) (*TaskListResponse, error)
	SubtasksByProject(context.Context, *ProjectIDRequest) (*SubtaskListResponse, error)
	SubtasksWithTime(context.Context, *TaskIDRequest) (*SubtaskListResponse, error)
	CreateTask(context.Context, *CreateTaskRequest) (*TaskResponse, error)
	DeleteTask(context.Context, *IDRequest) (*Empty, error)
	CreateSubtask(context.Context, *CreateSubtaskRequest) (*SubtaskResponse, error)
	DeleteSubtask(context.Context, *IDRequest) (*Empty, error)
	MoveTask(context.Context, *MoveRequest) (*Empty, error)
	MoveSubtask(context.Context, *MoveRequest) (*Empty, error)
	UpdateTaskTitle(context.Context, *TitleRequest) (*Empty, error)
	UpdateSubtaskTitle(context.Context, *TitleRequest) (*Empty, error)
	TaskDescription(context.Context, *IDRequest) (*StringResponse, error)
	SubtaskDescription(context.Context, *IDRequest) (*StringResponse, error)
	UpdateTaskDescription(context.Context, *TextRequest) (*Empty, error)
	UpdateSubtaskDescription(context.Context, *TextRequest) (*Empty, error)
	// Ссылки задач и подзадач.
	TaskLinks(context.Context, *TaskIDRequest) (*LinkListResponse, error)
	SubtaskLinks(context.Context, *SubtaskIDRequest) (*LinkListResponse, error)
	CreateTaskLink(context.Context, *LinkOwnerRequest) (*LinkResponse, error)
	UpdateTaskLink(context.Context, *LinkNameRequest) (*LinkResponse, error)
	CreateSubtaskLink(context.Context, *LinkOwnerRequest) (*LinkResponse, error)
	UpdateSubtaskLink(context.Context, *LinkNameRequest) (*LinkResponse, error)
	DeleteTaskLink(context.Context, *IDRequest) (*Empty, error)
	DeleteSubtaskLink(context.Context, *IDRequest) (*Empty, error)
	// Журнал подзадач.
	JournalEntries(context.Context, *SubtaskIDRequest) (*JournalEntryListResponse, error)
	CreateJournalEntry(context.Context, *JournalTextRequest) (*JournalEntryResponse, error)
	UpdateJournalEntry(context.Context, *JournalTextRequest) (*Empty, error)
	JournalTexts(context.Context, *ProjectIDRequest) (*JournalTextsResponse, error)
	// Чек-листы подзадач.
	ChecklistItems(context.Context, *SubtaskIDRequest) (*ChecklistItemListResponse, error)
	ChecklistCounts(context.Context, *ProjectIDRequest) (*ChecklistCountsResponse, error)
	CreateChecklistItem(context.Context, *JournalTextRequest) (*ChecklistItemResponse, error)
	UpdateChecklistItemText(context.Context, *JournalTextRequest) (*Empty, error)
	SetChecklistItemStatus(context.Context, *ChecklistStatusRequest) (*Empty, error)
	MoveChecklistItem(context.Context, *MoveRequest) (*Empty, error)
	DeleteChecklistItem(context.Context, *IDRequest) (*Empty, error)
	// Учёт времени.
	StartSession(context.Context, *TimeRequest) (*Empty, error)
	StopSession(context.Context, *TimeRequest) (*Empty, error)
	TimeEntriesBySubtask(context.Context, *SubtaskIDRequest) (*TimeEntryListResponse, error)
	RunningSession(context.Context, *Empty) (*RunningSessionResponse, error)
	TodayTotal(context.Context, *Empty) (*DurationResponse, error)
	WeeklyTotal(context.Context, *Empty) (*DurationResponse, error)
	// Отчёты.
	ReportEntries(context.Context, *RangeRequest) (*ReportEntryListResponse, error)
	JournalEntriesByRange(context.Context, *RangeNoProjectRequest) (*ReportJournalEntryListResponse, error)
	TagsByTasks(context.Context, *TagsByTasksRequest) (*TagsMapResponse, error)
	// Каталог статусов и история.
	ListStatuses(context.Context, *Empty) (*StatusListResponse, error)
	CreateStatus(context.Context, *StatusRequest) (*StatusResponse, error)
	UpdateStatus(context.Context, *StatusUpdateRequest) (*Empty, error)
	DeleteStatus(context.Context, *IDRequest) (*Empty, error)
	SetStatus(context.Context, *SetStatusRequest) (*Empty, error)
	StatusHistory(context.Context, *HistoryRequest) (*HistoryListResponse, error)
	// Каталог типов тегов и теги задач.
	ListTagTypes(context.Context, *Empty) (*TagTypeListResponse, error)
	CreateTagType(context.Context, *TagTypeRequest) (*TagTypeResponse, error)
	UpdateTagType(context.Context, *TagTypeUpdateRequest) (*Empty, error)
	DeleteTagType(context.Context, *IDRequest) (*Empty, error)
	TaskTags(context.Context, *TaskIDRequest) (*TagListResponse, error)
	TagsByProject(context.Context, *ProjectIDRequest) (*TagsMapResponse, error)
	CreateTag(context.Context, *TagRequest) (*TagResponse, error)
	UpdateTag(context.Context, *TagUpdateRequest) (*Empty, error)
	DeleteTag(context.Context, *IDRequest) (*Empty, error)
	// Настройки.
	GetSetting(context.Context, *SettingRequest) (*GetSettingResponse, error)
	SetSetting(context.Context, *SettingRequest) (*Empty, error)
	mustEmbedUnimplementedTaskyServer()
}

